def plus_one(function):
    def wrapped(value):
        return function(value) + 1
    return wrapped

def square(value):
    return value * value

changed = plus_one(square)
print(changed(3))
from functools import wraps

def keep_name(function):
    @wraps(function)
    def wrapped(value):
        return function(value)
    return wrapped

def square(value):
    return value * value

named = keep_name(square)
print(named.__name__)
print(named(3))
